package estate.svc;

import estate.api.Context;
import estate.api.Service;
import estate.api.ServiceException;

import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

/** Notifier: sends marketing offers queued by the customer service. A "send" is a row in `sent`. */
public class Main implements Service {
    private Context ctx;
    private Connection db;

    @Override
    public void start(Context c) throws Exception {
        this.ctx = c;
        this.db = c.db();
        try (Statement s = db.createStatement()) {
            s.execute("CREATE TABLE IF NOT EXISTS sent(id BIGINT AUTO_INCREMENT PRIMARY KEY, customer_id VARCHAR(40) NOT NULL, "
                    + "offer_id VARCHAR(40) NOT NULL, ts BIGINT NOT NULL)");
            s.execute("CREATE TABLE IF NOT EXISTS offer_day(customer_id VARCHAR(40) NOT NULL, offer_day BIGINT NOT NULL, "
                    + "sent_count BIGINT NOT NULL, PRIMARY KEY(customer_id, offer_day))");
            s.execute("CREATE TABLE IF NOT EXISTS dropped_offers(customer_id VARCHAR(40) PRIMARY KEY, dropped_count BIGINT NOT NULL)");
            s.execute("MERGE INTO offer_day(customer_id, offer_day, sent_count) KEY(customer_id, offer_day) "
                    + "SELECT customer_id, CAST(FLOOR(ts / 100.0) AS BIGINT), COUNT(*) FROM sent "
                    + "GROUP BY customer_id, CAST(FLOOR(ts / 100.0) AS BIGINT)");
        }
    }

    @Override
    public void onEvent(String topic, Map<String, String> ev) throws Exception {
        if (!"offer.queued".equals(topic)) return;
        boolean oldAutoCommit = db.getAutoCommit();
        try {
            db.setAutoCommit(false);
            String customerId = ev.get("customerId");
            long now = ctx.now();
            long day = now / 100;
            try (PreparedStatement ensureDay = db.prepareStatement(
                    "INSERT INTO offer_day(customer_id, offer_day, sent_count) "
                            + "SELECT ?, ?, 0 WHERE NOT EXISTS "
                            + "(SELECT 1 FROM offer_day WHERE customer_id = ? AND offer_day = ?)")) {
                ensureDay.setString(1, customerId);
                ensureDay.setLong(2, day);
                ensureDay.setString(3, customerId);
                ensureDay.setLong(4, day);
                ensureDay.executeUpdate();
            }

            long sentToday;
            try (PreparedStatement q = db.prepareStatement(
                    "SELECT sent_count FROM offer_day WHERE customer_id = ? AND offer_day = ? FOR UPDATE")) {
                q.setString(1, customerId);
                q.setLong(2, day);
                try (ResultSet rs = q.executeQuery()) {
                    rs.next();
                    sentToday = rs.getLong(1);
                }
            }

            if (sentToday < 2) {
                try (PreparedStatement ins = db.prepareStatement(
                        "INSERT INTO sent(customer_id, offer_id, ts) VALUES (?,?,?)")) {
                    ins.setString(1, customerId);
                    ins.setString(2, ev.get("offerId"));
                    ins.setLong(3, now);
                    ins.executeUpdate();
                }
                try (PreparedStatement update = db.prepareStatement(
                        "UPDATE offer_day SET sent_count = sent_count + 1 WHERE customer_id = ? AND offer_day = ?")) {
                    update.setString(1, customerId);
                    update.setLong(2, day);
                    update.executeUpdate();
                }
            } else {
                try (PreparedStatement ensureDropped = db.prepareStatement(
                        "INSERT INTO dropped_offers(customer_id, dropped_count) "
                                + "SELECT ?, 0 WHERE NOT EXISTS "
                                + "(SELECT 1 FROM dropped_offers WHERE customer_id = ?)")) {
                    ensureDropped.setString(1, customerId);
                    ensureDropped.setString(2, customerId);
                    ensureDropped.executeUpdate();
                }
                try (PreparedStatement update = db.prepareStatement(
                        "UPDATE dropped_offers SET dropped_count = dropped_count + 1 WHERE customer_id = ?")) {
                    update.setString(1, customerId);
                    update.executeUpdate();
                }
            }
            db.commit();
        } catch (Exception e) {
            db.rollback();
            throw e;
        } finally {
            db.setAutoCommit(oldAutoCommit);
        }
    }

    @Override
    public Map<String, String> handle(String op, Map<String, String> req) throws ServiceException {
        try {
            switch (op) {
                case "health": {
                    try (Statement s = db.createStatement(); ResultSet rs = s.executeQuery("SELECT COUNT(*) FROM sent")) { rs.next(); }
                    return Map.of("status", "UP");
                }
                case "sent": return sent(req);
                default: throw new ServiceException("error", "unknown op " + op);
            }
        } catch (ServiceException e) {
            throw e;
        } catch (Exception e) {
            throw new ServiceException("error", String.valueOf(e.getMessage()));
        }
    }

    /** Messages sent to a customer: count, send ticks, and the number dropped by the daily cap. */
    private Map<String, String> sent(Map<String, String> req) throws Exception {
        try (PreparedStatement q = db.prepareStatement("SELECT ts FROM sent WHERE customer_id = ? ORDER BY id")) {
            q.setString(1, req.get("customerId"));
            StringBuilder ticks = new StringBuilder();
            int n = 0;
            try (ResultSet rs = q.executeQuery()) {
                while (rs.next()) { if (n++ > 0) ticks.append(','); ticks.append(rs.getLong(1)); }
            }
            long capped = 0;
            try (PreparedStatement dropped = db.prepareStatement(
                    "SELECT dropped_count FROM dropped_offers WHERE customer_id = ?")) {
                dropped.setString(1, req.get("customerId"));
                try (ResultSet rs = dropped.executeQuery()) {
                    if (rs.next()) capped = rs.getLong(1);
                }
            }
            return Map.of("count", String.valueOf(n), "ticks", ticks.toString(), "capped", String.valueOf(capped));
        }
    }
}

