package estate.svc;

import org.junit.jupiter.api.Test;

import java.util.Map;

import static org.junit.jupiter.api.Assertions.*;

class MainTest {
    @Test
    void queuedOfferIsSent() throws Exception {
        FakeContext c = new FakeContext();
        Main m = new Main();
        m.start(c);
        c.tick = 7;
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o1"));
        Map<String, String> r = m.handle("sent", Map.of("customerId", "c1"));
        assertEquals("1", r.get("count"));
        assertEquals("7", r.get("ticks"));
        assertEquals("0", r.get("capped"));
    }

    @Test
    void dropsOffersAfterTwoInTheSameDayAndReportsCumulativeDrops() throws Exception {
        FakeContext c = new FakeContext();
        Main m = new Main();
        m.start(c);
        c.tick = 199;
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o1"));
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o2"));
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o3"));
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o4"));

        Map<String, String> r = m.handle("sent", Map.of("customerId", "c1"));
        assertEquals("2", r.get("count"));
        assertEquals("199,199", r.get("ticks"));
        assertEquals("2", r.get("capped"));
    }

    @Test
    void dailyCapResetsOnTheNextDay() throws Exception {
        FakeContext c = new FakeContext();
        Main m = new Main();
        m.start(c);
        c.tick = 100;
        for (int i = 1; i <= 3; i++) {
            m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o" + i));
        }
        c.tick = 200;
        m.onEvent("offer.queued", Map.of("customerId", "c1", "offerId", "o4"));

        Map<String, String> r = m.handle("sent", Map.of("customerId", "c1"));
        assertEquals("3", r.get("count"));
        assertEquals("100,100,200", r.get("ticks"));
        assertEquals("1", r.get("capped"));
    }

    @Test
    void healthIsUp() throws Exception {
        Main m = new Main();
        m.start(new FakeContext());
        assertEquals("UP", m.handle("health", Map.of()).get("status"));
    }
}

